import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong();
        // lengths[x]: length of the run whose endpoint is x (only endpoints stay accurate)
        HashMap<Long, Integer> lengths = new HashMap<>(n * 4);
        int best = 0;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            long x = nextLong();
            if (!lengths.containsKey(x)) {
                int left = lengths.getOrDefault(x - 1, 0), right = lengths.getOrDefault(x + 1, 0);
                int total = left + right + 1;
                lengths.put(x, total);
                lengths.put(x - left, total);
                lengths.put(x + right, total);
                best = Math.max(best, total);
            }
            if (i > 0) sb.append(' ');
            sb.append(best);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n := next()
	// lengths[x]: length of the run whose endpoint is x (only endpoints stay accurate)
	lengths := make(map[int]int, n*4)
	best := 0
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < n; i++ {
		x := next()
		if _, ok := lengths[x]; !ok {
			left, right := lengths[x-1], lengths[x+1]
			total := left + right + 1
			lengths[x] = total
			lengths[x-left] = total
			lengths[x+right] = total
			best = max(best, total)
		}
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(best))
	}
	w.WriteByte('\n')
}
